CREATE TABLE decimal_test (
    id int,
    big_decimal decimal(50,15),    
    huge_decimal decimal(76,20),   
    max_decimal decimal(76,0)      
) ENGINE=OLAP
DUPLICATE KEY(id)
DISTRIBUTED BY HASH(id) BUCKETS 1
PROPERTIES (
    "replication_num" = "1"
);
